// JSON imports widen string literals, so fixtures are read through this typed helper.
// The files are generated by `uv run python -m poker_trainer.api.dev_fixtures` (see the backend).
import type { AttemptResult, PuzzleView, SettingsView } from '../api/types'

const files = import.meta.glob<unknown>('./fixtures/*.json', { eager: true, import: 'default' })

export type FixtureName = `puzzle_${string}` | `attempt_${string}` | 'settings'

/** Loads `src/test/fixtures/<name>.json`, trusting the caller's type (the files come from the API). */
export function fixture<T = PuzzleView>(name: FixtureName): T {
  const data = files[`./fixtures/${name}.json`]
  if (data === undefined) throw new Error(`no fixture named ${name}`)
  return data as T
}

export function fixtureNames(): FixtureName[] {
  return Object.keys(files)
    .map((path) => path.replace(/^\.\/fixtures\//, '').replace(/\.json$/, '') as FixtureName)
    .sort()
}

export const puzzleFixture = (name: string): PuzzleView => fixture<PuzzleView>(`puzzle_${name}`)
export const attemptFixture = (name: string): AttemptResult =>
  fixture<AttemptResult>(`attempt_${name}`)
export const settingsFixture = (): SettingsView => fixture<SettingsView>('settings')
